"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { AlertCircleIcon, ImagePlusIcon, Loader2Icon, Maximize2Icon } from "lucide-react";
import { errorMessage, useImageEditor } from "photocn/react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlurCenterOverlay } from "./blur-center-overlay";
import {
  CornerHandlesOverlay,
  CropFrameOverlay,
  fitView,
  rectToStage,
  type StageSize,
  type StageView,
} from "./crop-overlay";

export interface ImageEditorCanvasProps {
  className?: string;
  /** Accessible name of the image. */
  alt?: string;
  /** Allow dropping an image file onto the canvas. Default `true`. */
  allowDrop?: boolean;
  /** Show an "Open image" button in the empty state. Default `true`. */
  showOpenButton?: boolean;
  /** Replace the empty state (no image loaded yet). */
  emptyState?: ReactNode;
  /** Space (px) kept around the image. Default 24. */
  padding?: number;
  /** Extra layers rendered above the image, positioned over it. */
  children?: ReactNode;
}

type UserView = { scale: number; x: number; y: number };
const IDENTITY_VIEW: UserView = { scale: 1, x: 0, y: 0 };

const SETTLE_MS = 240;
const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

/**
 * Blend two views so the point under the stage center travels in a straight
 * line and the zoom changes geometrically (no wobble).
 */
function blendViews(from: StageView, to: StageView, stage: StageSize, t: number): StageView {
  const cx = stage.width / 2;
  const cy = stage.height / 2;
  const fromX = (cx - from.ox) / from.k;
  const fromY = (cy - from.oy) / from.k;
  const toX = (cx - to.ox) / to.k;
  const toY = (cy - to.oy) / to.k;
  const k = from.k * (to.k / from.k) ** t;
  const x = fromX + (toX - fromX) * t;
  const y = fromY + (toY - fromY) * t;
  return { k, ox: cx - x * k, oy: cy - y * k };
}

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(query.matches);
    const onChange = () => setReduced(query.matches);
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

/**
 * The image stage. In the crop tool it shows the whole image dimmed around
 * the crop frame (drag handles, move, zoom, perspective corners); in every
 * other tool it shows the result, with pinch/⌘-scroll zoom, blur focus and
 * press-and-hold to compare.
 */
export function ImageEditorCanvas({
  className,
  alt = "Image being edited",
  allowDrop = true,
  showOpenButton = true,
  emptyState,
  padding = 24,
  children,
}: ImageEditorCanvasProps) {
  const editor = useImageEditor();
  const { geometry } = editor;
  const [stage, setStage] = useState<StageSize | null>(null);
  const [frozenView, setFrozenView] = useState<StageView | null>(null);
  // After a drag, ease from the frozen view to the re-fitted one (Photos-style).
  const [settle, setSettle] = useState<{ from: StageView; start: number } | null>(null);
  const [, setFrame] = useState(0);
  const reducedMotion = usePrefersReducedMotion();
  const freezeView = (next: StageView | null) => {
    if (next === null && frozenView && !reducedMotion) {
      setSettle({ from: frozenView, start: performance.now() });
    } else if (next !== null) {
      setSettle(null);
    }
    setFrozenView(next);
  };
  useEffect(() => {
    if (!settle) return;
    let raf = 0;
    const tick = () => {
      if (performance.now() - settle.start >= SETTLE_MS) {
        setSettle(null);
        return;
      }
      setFrame((frame) => frame + 1);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [settle]);
  const [userView, setUserView] = useState<UserView>(IDENTITY_VIEW);
  const [isDragOver, setIsDragOver] = useState(false);
  const stageRef = editor.stageRef;

  const isCropView = geometry.view === "full";
  const isCorners = geometry.editingCorners;
  const isBlur = editor.tool === "blur";

  // Measure the stage.
  useLayoutEffect(() => {
    const element = stageRef.current;
    if (!element) return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      setStage((prev) =>
        prev && prev.width === width && prev.height === height ? prev : { width, height },
      );
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [stageRef, editor.imageSrc]);

  // A new image, or switching between crop and result, starts un-zoomed.
  const viewKey = `${editor.imageSrc}|${geometry.view}`;
  const [trackedKey, setTrackedKey] = useState(viewKey);
  if (viewKey !== trackedKey) {
    setTrackedKey(viewKey);
    setUserView(IDENTITY_VIEW);
    setFrozenView(null);
    setSettle(null);
  }

  const oriented = geometry.orientedSize;
  let view: StageView | null = null;
  if (stage && oriented) {
    if (frozenView) {
      view = frozenView;
    } else if (isCropView) {
      // The frame stays put: fit the crop (or, while dragging corners, the
      // whole image) and let the image move and zoom under it.
      view = fitView(isCorners ? geometry.bounds : geometry.crop, oriented, stage, padding * 1.5);
      if (settle) {
        const t = Math.min(1, (performance.now() - settle.start) / SETTLE_MS);
        view = blendViews(settle.from, view, stage, easeOutCubic(t));
      }
    } else {
      const fit = fitView(geometry.displayRect, oriented, stage, padding);
      view = {
        k: fit.k * userView.scale,
        ox: fit.ox * userView.scale + userView.x,
        oy: fit.oy * userView.scale + userView.y,
      };
    }
  }
  const canvasBox = view && oriented ? rectToStage(view, oriented, geometry.displayRect) : null;

  // ⌘/Ctrl-scroll or pinch zooms the result; plain scroll pans once zoomed.
  const zoomRef = useRef<(event: WheelEvent) => void>(() => {});
  zoomRef.current = (event: WheelEvent) => {
    if (isCropView || !stage) return;
    const zooming = event.ctrlKey || event.metaKey;
    if (!zooming && userView.scale === 1) return;
    event.preventDefault();
    const rect = stageRef.current!.getBoundingClientRect();
    const cx = event.clientX - rect.left;
    const cy = event.clientY - rect.top;
    setUserView((prev) => {
      if (!zooming) return { ...prev, x: prev.x - event.deltaX, y: prev.y - event.deltaY };
      const scale = Math.min(8, Math.max(1, prev.scale * Math.exp(-event.deltaY * 0.01)));
      const f = scale / prev.scale;
      if (scale === 1) return IDENTITY_VIEW;
      return { scale, x: cx - (cx - prev.x) * f, y: cy - (cy - prev.y) * f };
    });
  };
  useEffect(() => {
    const element = stageRef.current;
    if (!element) return;
    const onWheel = (event: WheelEvent) => zoomRef.current(event);
    element.addEventListener("wheel", onWheel, { passive: false });
    return () => element.removeEventListener("wheel", onWheel);
  }, [stageRef, editor.imageSrc]);

  // Press and hold the result to see the original.
  const comparePointer = useRef<number | null>(null);
  const canCompare = !isCropView && !isBlur && !editor.disabled;
  const onStagePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!canCompare || (event.pointerType === "mouse" && event.button !== 0)) return;
    comparePointer.current = event.pointerId;
    event.currentTarget.setPointerCapture(event.pointerId);
    editor.compare.setActive(true);
  };
  const endCompare = (event: PointerEvent<HTMLDivElement>) => {
    if (comparePointer.current !== event.pointerId) return;
    comparePointer.current = null;
    editor.compare.setActive(false);
  };

  const dropProps = allowDrop
    ? {
        onDragOver: (event: DragEvent) => {
          if (!Array.from(event.dataTransfer.items).some((item) => item.kind === "file")) return;
          event.preventDefault();
          setIsDragOver(true);
        },
        onDragLeave: () => setIsDragOver(false),
        onDrop: (event: DragEvent) => {
          const file = Array.from(event.dataTransfer.files).find((candidate) =>
            candidate.type.startsWith("image/"),
          );
          setIsDragOver(false);
          if (!file || editor.disabled) return;
          event.preventDefault();
          void editor.load(file).catch(() => undefined);
        },
      }
    : {};

  return (
    <div
      className={cn("relative h-full min-h-0", className)}
      data-drag-over={isDragOver || undefined}
      data-slot="image-editor-canvas"
      data-settling={settle ? "" : undefined}
      data-view={isCropView ? "crop" : "result"}
      {...dropProps}
    >
      {editor.imageSrc ? (
        <div
          className={cn(
            "relative size-full touch-none overflow-hidden rounded-md border bg-muted/40 select-none",
            "bg-[conic-gradient(var(--muted)_25%,transparent_0_50%,var(--muted)_0_75%,transparent_0)] bg-[length:16px_16px]",
          )}
          data-slot="image-editor-stage"
          onPointerCancel={endCompare}
          onPointerDown={onStagePointerDown}
          onPointerUp={endCompare}
          ref={stageRef}
        >
          {/* One <canvas> for the image's lifetime: transferControlToOffscreen is one-shot. */}
          <canvas
            aria-label={alt}
            className="pointer-events-none absolute block"
            key={editor.imageSrc}
            ref={editor.canvasRef}
            role="img"
            style={
              canvasBox
                ? { left: canvasBox.left, top: canvasBox.top, width: canvasBox.width, height: canvasBox.height }
                : { visibility: "hidden" }
            }
          />
          {!editor.isReady && editor.status !== "error" ? (
            <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
              <Loader2Icon className="size-5 animate-spin text-muted-foreground" />
            </div>
          ) : null}
          {view && stage && isCropView && !isCorners ? (
            <CropFrameOverlay
              disabled={editor.disabled}
              geometry={geometry}
              onFreezeView={freezeView}
              stage={stage}
              view={view}
            />
          ) : null}
          {view && stage && isCropView && isCorners ? (
            <CornerHandlesOverlay
              disabled={editor.disabled}
              geometry={geometry}
              onFreezeView={freezeView}
              stage={stage}
              view={view}
            />
          ) : null}
          {canvasBox && !isCropView ? (
            <div className="pointer-events-none absolute" style={canvasBox}>
              {isBlur ? (
                <BlurCenterOverlay
                  centerX={editor.blur.value.centerX}
                  centerY={editor.blur.value.centerY}
                  className="pointer-events-auto"
                  disabled={editor.disabled}
                  onCenterChange={editor.blur.setCenter}
                  onCenterCommit={editor.blur.commitCenter}
                />
              ) : null}
              {children}
            </div>
          ) : null}
          {!isCropView && userView !== IDENTITY_VIEW ? (
            <Button
              aria-label="Fit to screen"
              className="absolute right-2 bottom-2"
              onClick={() => setUserView(IDENTITY_VIEW)}
              onPointerDown={(event) => event.stopPropagation()}
              size="icon-sm"
              type="button"
              variant="secondary"
            >
              <Maximize2Icon />
            </Button>
          ) : null}
        </div>
      ) : (
        (emptyState ?? <ImageEditorEmptyState showOpenButton={showOpenButton} />)
      )}
      {isDragOver ? (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center rounded-md border-2 border-dashed border-primary bg-primary/5 text-sm font-medium text-primary">
          Drop to open
        </div>
      ) : null}
    </div>
  );
}

/** Shown before an image is loaded, and when loading fails. */
export function ImageEditorEmptyState({
  showOpenButton = true,
  className,
}: {
  showOpenButton?: boolean;
  className?: string;
}) {
  const editor = useImageEditor();
  const error = editor.status === "error" ? editor.error : null;
  return (
    <div
      className={cn("flex h-full min-h-72 flex-col items-center justify-center p-6", className)}
      data-slot="image-editor-empty-state"
    >
      <Alert
        className={cn(
          "flex max-w-md flex-col items-center gap-2 text-center [&>svg]:translate-y-0",
          Boolean(error) && "border-destructive/30 bg-destructive/10",
        )}
        variant={error ? "destructive" : "default"}
      >
        {error ? <AlertCircleIcon aria-hidden="true" /> : null}
        {error ? <AlertTitle>Couldn&apos;t open this image</AlertTitle> : null}
        <AlertDescription className="items-center text-center">
          {error
            ? errorMessage(error)
            : editor.isLoading
              ? "Loading image…"
              : "Open or drop an image to start editing."}
        </AlertDescription>
        {showOpenButton ? (
          <Button
            disabled={editor.isLoading || editor.disabled}
            onClick={() => void editor.openFile()}
            size="sm"
            type="button"
            variant="outline"
          >
            <ImagePlusIcon aria-hidden="true" data-icon="inline-start" />
            {error ? "Open another image" : "Open image"}
          </Button>
        ) : null}
      </Alert>
    </div>
  );
}

"use client";

import { useEffect, useRef, type KeyboardEvent as ReactKeyboardEvent, type PointerEvent } from "react";
import {
  fitRectInPolygon,
  rectInsidePolygon,
  type NormalizedRect,
  type Quad,
  type Vec2,
} from "photocn";
import type { ImageEditorGeometryApi } from "photocn/react";

import { cn } from "@/lib/utils";

/** Maps oriented px (X, Y) to stage px: (ox + X·k, oy + Y·k). */
export interface StageView {
  k: number;
  ox: number;
  oy: number;
}

export interface StageSize {
  width: number;
  height: number;
}

type Size = { width: number; height: number };

/** View that fits `rect` (normalized oriented) inside the stage with padding. */
export function fitView(rect: NormalizedRect, oriented: Size, stage: StageSize, padding: number): StageView {
  const rw = Math.max(1e-6, rect.width * oriented.width);
  const rh = Math.max(1e-6, rect.height * oriented.height);
  const k = Math.max(
    1e-6,
    Math.min((stage.width - padding * 2) / rw, (stage.height - padding * 2) / rh),
  );
  return {
    k,
    ox: stage.width / 2 - (rect.x * oriented.width + rw / 2) * k,
    oy: stage.height / 2 - (rect.y * oriented.height + rh / 2) * k,
  };
}

export function toStage(view: StageView, oriented: Size, [x, y]: Vec2): Vec2 {
  return [view.ox + x * oriented.width * view.k, view.oy + y * oriented.height * view.k];
}

export function toNormalized(view: StageView, oriented: Size, [x, y]: Vec2): Vec2 {
  return [(x - view.ox) / (oriented.width * view.k), (y - view.oy) / (oriented.height * view.k)];
}

export function rectToStage(view: StageView, oriented: Size, rect: NormalizedRect) {
  const [left, top] = toStage(view, oriented, [rect.x, rect.y]);
  return {
    left,
    top,
    width: rect.width * oriented.width * view.k,
    height: rect.height * oriented.height * view.k,
  };
}

type Handle = "n" | "s" | "e" | "w" | "ne" | "nw" | "se" | "sw";

const HANDLES: { id: Handle; label: string; className: string }[] = [
  { id: "nw", label: "Resize from top left", className: "left-0 top-0 cursor-nwse-resize" },
  { id: "n", label: "Resize from top", className: "left-1/2 top-0 cursor-ns-resize" },
  { id: "ne", label: "Resize from top right", className: "left-full top-0 cursor-nesw-resize" },
  { id: "e", label: "Resize from right", className: "left-full top-1/2 cursor-ew-resize" },
  { id: "se", label: "Resize from bottom right", className: "left-full top-full cursor-nwse-resize" },
  { id: "s", label: "Resize from bottom", className: "left-1/2 top-full cursor-ns-resize" },
  { id: "sw", label: "Resize from bottom left", className: "left-0 top-full cursor-nesw-resize" },
  { id: "w", label: "Resize from left", className: "left-0 top-1/2 cursor-ew-resize" },
];

/** Resize a px rect by a pointer delta from one handle, honoring a locked ratio. */
function resizeRect(
  start: { x: number; y: number; w: number; h: number },
  handle: Handle,
  dx: number,
  dy: number,
  ratio: number | null,
  min: number,
) {
  let { x, y, w, h } = start;
  const east = handle.includes("e");
  const west = handle.includes("w");
  const north = handle.includes("n");
  const south = handle.includes("s");

  if (!ratio) {
    if (east) w = Math.max(min, start.w + dx);
    if (west) {
      w = Math.max(min, start.w - dx);
      x = start.x + start.w - w;
    }
    if (south) h = Math.max(min, start.h + dy);
    if (north) {
      h = Math.max(min, start.h - dy);
      y = start.y + start.h - h;
    }
    return { x, y, w, h };
  }

  const isCorner = (east || west) && (north || south);
  if (isCorner) {
    // Follow whichever axis moved more, keep the opposite corner anchored.
    const dw = east ? dx : -dx;
    const dh = south ? dy : -dy;
    w = Math.max(min, Math.abs(dw) >= Math.abs(dh * ratio) ? start.w + dw : start.w + dh * ratio);
    h = w / ratio;
    if (h < min) {
      h = min;
      w = h * ratio;
    }
    x = west ? start.x + start.w - w : start.x;
    y = north ? start.y + start.h - h : start.y;
  } else if (east || west) {
    w = Math.max(min, start.w + (east ? dx : -dx));
    h = w / ratio;
    x = west ? start.x + start.w - w : start.x;
    y = start.y + start.h / 2 - h / 2;
  } else {
    h = Math.max(min, start.h + (south ? dy : -dy));
    w = h * ratio;
    y = north ? start.y + start.h - h : start.y;
    x = start.x + start.w / 2 - w / 2;
  }
  return { x, y, w, h };
}

/** Largest t in [0, 1] for which `candidate(t)` is valid (binary search). */
function constrain<T>(candidate: (t: number) => T, valid: (value: T) => boolean): T {
  if (valid(candidate(1))) return candidate(1);
  let lo = 0;
  let hi = 1;
  for (let i = 0; i < 24; i++) {
    const mid = (lo + hi) / 2;
    if (valid(candidate(mid))) lo = mid;
    else hi = mid;
  }
  return candidate(lo);
}

type Drag =
  | { kind: "resize"; handle: Handle; pointerId: number; start: Vec2; rect: NormalizedRect; view: StageView }
  | { kind: "pan"; pointerId: number; start: Vec2; rect: NormalizedRect; view: StageView };

export interface CropFrameOverlayProps {
  geometry: ImageEditorGeometryApi;
  view: StageView;
  stage: StageSize;
  disabled?: boolean;
  /** Freeze the view during a handle drag (null to release). */
  onFreezeView: (view: StageView | null) => void;
}

const MIN_CROP_PX = 32;

/**
 * The crop frame: dimmed outside, rule-of-thirds inside, 8 handles. Drag a
 * handle to resize, drag inside to move the image under the frame, scroll
 * or pinch to zoom. Everything is limited to the (warped) image.
 */
export function CropFrameOverlay({ geometry, view, stage, disabled, onFreezeView }: CropFrameOverlayProps) {
  const oriented = geometry.orientedSize;
  const polygon = geometry.polygon;
  const drag = useRef<Drag | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const escRef = useRef<((event: KeyboardEvent) => void) | null>(null);
  const wheelRef = useRef<(event: WheelEvent) => void>(() => {});
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    // Native + non-passive so zooming the crop doesn't also scroll the page.
    const onWheel = (event: WheelEvent) => wheelRef.current(event);
    root.addEventListener("wheel", onWheel, { passive: false });
    return () => root.removeEventListener("wheel", onWheel);
  }, [oriented, polygon]);
  if (!oriented || !polygon) return null;

  const frame = rectToStage(view, oriented, geometry.crop);
  const ratio = geometry.value.aspectRatio;
  const inside = (rect: NormalizedRect) => rectInsidePolygon(rect, polygon, oriented);

  const toNorm = (r: { x: number; y: number; w: number; h: number }): NormalizedRect => ({
    x: r.x / oriented.width,
    y: r.y / oriented.height,
    width: r.w / oriented.width,
    height: r.h / oriented.height,
  });
  const toPx = (r: NormalizedRect) => ({
    x: r.x * oriented.width,
    y: r.y * oriented.height,
    w: r.width * oriented.width,
    h: r.height * oriented.height,
  });

  const resizeBy = (handle: Handle, rect: NormalizedRect, k: number, dx: number, dy: number) =>
    constrain(
      (t) => toNorm(resizeRect(toPx(rect), handle, (dx * t) / k, (dy * t) / k, ratio, MIN_CROP_PX / k)),
      inside,
    );

  const panBy = (rect: NormalizedRect, k: number, dx: number, dy: number) =>
    constrain(
      (t) => ({
        ...rect,
        x: rect.x - (dx * t) / k / oriented.width,
        y: rect.y - (dy * t) / k / oriented.height,
      }),
      inside,
    );

  const begin = (event: PointerEvent<HTMLElement>, handle: Handle | null) => {
    if (disabled || (event.pointerType === "mouse" && event.button !== 0)) return;
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);
    const common = {
      pointerId: event.pointerId,
      start: [event.clientX, event.clientY] as Vec2,
      rect: geometry.crop,
      view,
    };
    drag.current = handle ? { kind: "resize", handle, ...common } : { kind: "pan", ...common };
    if (handle) onFreezeView(view);
    // Esc puts the crop back where the drag started (no undo step).
    const onKey = (keyEvent: KeyboardEvent) => {
      if (keyEvent.key !== "Escape" || !drag.current) return;
      keyEvent.preventDefault();
      keyEvent.stopPropagation();
      drag.current = null;
      geometry.cancel();
      onFreezeView(null);
      stopEsc();
    };
    stopEsc();
    escRef.current = onKey;
    window.addEventListener("keydown", onKey, true);
  };

  const stopEsc = () => {
    if (escRef.current) window.removeEventListener("keydown", escRef.current, true);
    escRef.current = null;
  };

  const move = (event: PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== event.pointerId) return;
    const dx = event.clientX - d.start[0];
    const dy = event.clientY - d.start[1];
    const next =
      d.kind === "resize"
        ? resizeBy(d.handle, d.rect, d.view.k, dx, dy)
        : panBy(d.rect, view.k, dx, dy);
    geometry.setCrop(next, { transient: true });
  };

  const end = (event: PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== event.pointerId) return;
    drag.current = null;
    stopEsc();
    geometry.commit();
    onFreezeView(null);
  };

  wheelRef.current = (event: WheelEvent) => {
    if (disabled) return;
    event.preventDefault();
    const factor = Math.exp(event.deltaY * 0.002);
    const rect = geometry.crop;
    const cx = rect.x + rect.width / 2;
    const cy = rect.y + rect.height / 2;
    const minW = MIN_CROP_PX / view.k / oriented.width;
    const width = Math.max(minW, rect.width * factor);
    const height = (rect.height * width) / rect.width;
    let next: NormalizedRect = { x: cx - width / 2, y: cy - height / 2, width, height };
    if (!inside(next)) next = fitRectInPolygon(next, polygon, oriented);
    geometry.setCrop(next, { transient: true });
  };

  const onHandleKey = (handle: Handle) => (event: ReactKeyboardEvent<HTMLButtonElement>) => {
    const step = event.shiftKey ? 20 : 4;
    const delta: Record<string, Vec2> = {
      ArrowLeft: [-step, 0],
      ArrowRight: [step, 0],
      ArrowUp: [0, -step],
      ArrowDown: [0, step],
    };
    const d = delta[event.key];
    if (!d || disabled) return;
    event.preventDefault();
    geometry.setCrop(resizeBy(handle, geometry.crop, view.k, d[0], d[1]), { transient: true });
  };

  const maskPath = `M0 0H${stage.width}V${stage.height}H0Z M${frame.left} ${frame.top}v${frame.height}h${frame.width}v${-frame.height}Z`;

  return (
    <div className="absolute inset-0" data-slot="image-editor-crop-overlay" ref={rootRef}>
      <svg aria-hidden className="pointer-events-none absolute inset-0 size-full" height={stage.height} width={stage.width}>
        <path className="fill-black/55" d={maskPath} fillRule="evenodd" />
      </svg>
      <div
        aria-label="Crop area. Drag to move the image, scroll to zoom."
        className={cn(
          "absolute touch-none outline outline-1 -outline-offset-1 outline-white/90 shadow-[0_0_0_1px_rgba(0,0,0,0.35)]",
          disabled ? "pointer-events-none" : "cursor-move",
        )}
        onPointerCancel={end}
        onPointerDown={(event) => begin(event, null)}
        onPointerMove={move}
        onPointerUp={end}
        role="group"
        style={{ left: frame.left, top: frame.top, width: frame.width, height: frame.height }}
      >
        <div aria-hidden className="pointer-events-none absolute inset-0">
          <div className="absolute inset-y-0 left-1/3 w-px bg-white/40" />
          <div className="absolute inset-y-0 left-2/3 w-px bg-white/40" />
          <div className="absolute inset-x-0 top-1/3 h-px bg-white/40" />
          <div className="absolute inset-x-0 top-2/3 h-px bg-white/40" />
        </div>
        {HANDLES.map((handle) => (
          <button
            aria-label={handle.label}
            className={cn(
              "absolute z-10 flex size-7 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full outline-none touch-none focus-visible:ring-2 focus-visible:ring-ring",
              handle.className,
            )}
            disabled={disabled}
            key={handle.id}
            onKeyDown={onHandleKey(handle.id)}
            onKeyUp={() => geometry.commit()}
            onPointerCancel={end}
            onPointerDown={(event) => begin(event, handle.id)}
            onPointerMove={move}
            onPointerUp={end}
            type="button"
          >
            <span
              className={cn(
                "block rounded-full border border-black/30 bg-white shadow",
                handle.id.length === 2 ? "size-3.5" : "size-2.5",
              )}
            />
          </button>
        ))}
      </div>
    </div>
  );
}

export interface CornerHandlesOverlayProps {
  geometry: ImageEditorGeometryApi;
  view: StageView;
  stage: StageSize;
  disabled?: boolean;
  onFreezeView: (view: StageView | null) => void;
}

const CORNER_LABELS = ["top left", "top right", "bottom right", "bottom left"] as const;

/** Advanced perspective: drag each corner of the image. */
export function CornerHandlesOverlay({ geometry, view, stage, disabled, onFreezeView }: CornerHandlesOverlayProps) {
  const oriented = geometry.orientedSize;
  const polygon = geometry.polygon;
  const drag = useRef<{ index: 0 | 1 | 2 | 3; pointerId: number; view: StageView; origin: Vec2 } | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);
  if (!oriented || !polygon) return null;

  const points = polygon.map((p) => toStage(view, oriented, p)) as Quad;

  const begin = (index: 0 | 1 | 2 | 3) => (event: PointerEvent<HTMLButtonElement>) => {
    if (disabled) return;
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);
    const rect = event.currentTarget.parentElement!.getBoundingClientRect();
    drag.current = { index, pointerId: event.pointerId, view, origin: [rect.left, rect.top] };
    onFreezeView(view);
    const onKey = (keyEvent: KeyboardEvent) => {
      if (keyEvent.key !== "Escape" || !drag.current) return;
      keyEvent.preventDefault();
      keyEvent.stopPropagation();
      drag.current = null;
      geometry.cancel();
      onFreezeView(null);
      window.removeEventListener("keydown", onKey, true);
    };
    window.addEventListener("keydown", onKey, true);
    cleanupRef.current = () => window.removeEventListener("keydown", onKey, true);
  };
  const move = (event: PointerEvent<HTMLButtonElement>) => {
    const d = drag.current;
    if (!d || d.pointerId !== event.pointerId) return;
    const stagePoint: Vec2 = [event.clientX - d.origin[0], event.clientY - d.origin[1]];
    geometry.setCorner(d.index, toNormalized(d.view, oriented, stagePoint), { transient: true });
  };
  const end = (event: PointerEvent<HTMLButtonElement>) => {
    if (!drag.current || drag.current.pointerId !== event.pointerId) return;
    drag.current = null;
    cleanupRef.current?.();
    geometry.commit();
    onFreezeView(null);
  };

  return (
    <div className="absolute inset-0" data-slot="image-editor-corner-overlay">
      <svg aria-hidden className="pointer-events-none absolute inset-0 size-full" height={stage.height} width={stage.width}>
        <polygon
          className="fill-none stroke-white/90"
          points={points.map((p) => p.join(",")).join(" ")}
          strokeWidth={1.5}
        />
      </svg>
      {points.map((point, index) => (
        <button
          aria-label={`Move ${CORNER_LABELS[index]} corner`}
          className="absolute flex size-9 -translate-x-1/2 -translate-y-1/2 cursor-grab items-center justify-center rounded-full outline-none touch-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
          disabled={disabled}
          key={CORNER_LABELS[index]}
          onPointerCancel={end}
          onPointerDown={begin(index as 0 | 1 | 2 | 3)}
          onPointerMove={move}
          onPointerUp={end}
          style={{ left: point[0], top: point[1] }}
          type="button"
        >
          <span className="block size-4 rounded-full border-2 border-white bg-primary shadow" />
        </button>
      ))}
    </div>
  );
}

"use client";

import { useCallback, useRef, useState } from "react";

import { cn } from "@/lib/utils";

export interface BlurCenterOverlayProps {
  /** Normalized 0..1 position of the blur center within the displayed image rect. */
  centerX: number;
  centerY: number;
  disabled?: boolean;
  className?: string;
  /** Fires transient on drag and on pointer-up; the parent decides debouncing/commit. */
  onCenterChange?: (next: { centerX: number; centerY: number }) => void;
  onCenterCommit?: (next: { centerX: number; centerY: number }) => void;
}

function clamp01(value: number): number {
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}

export function BlurCenterOverlay({
  centerX,
  centerY,
  disabled = false,
  className,
  onCenterChange,
  onCenterCommit,
}: BlurCenterOverlayProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [dragging, setDragging] = useState(false);

  const positionFromEvent = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const container = containerRef.current;
      if (!container) return null;
      const rect = container.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) return null;
      return {
        centerX: clamp01((event.clientX - rect.left) / rect.width),
        centerY: clamp01((event.clientY - rect.top) / rect.height),
      };
    },
    [],
  );

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    if (event.button !== 0 && event.pointerType === "mouse") return;
    const pos = positionFromEvent(event);
    if (!pos) return;
    // Don't let pointerdown bubble up to the workspace's compare gesture —
    // clicking the blur handle should drag, not flash the original image.
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);
    setDragging(true);
    onCenterChange?.(pos);
  };

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    if (disabled || !dragging) return;
    const pos = positionFromEvent(event);
    if (!pos) return;
    onCenterChange?.(pos);
  };

  const endDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    setDragging(false);
    const pos = positionFromEvent(event);
    if (pos) onCenterCommit?.(pos);
  };

  return (
    <div
      className={cn(
        "absolute inset-0",
        disabled ? "pointer-events-none" : "pointer-events-auto cursor-crosshair",
        className,
      )}
      data-slot="blur-center-overlay"
      onPointerCancel={endDrag}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={endDrag}
      ref={containerRef}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute size-6 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white/90 bg-white/10 shadow-[0_0_0_2px_rgba(0,0,0,0.5)] transition-transform"
        style={{
          left: `${centerX * 100}%`,
          top: `${centerY * 100}%`,
          transform: dragging
            ? "translate(-50%, -50%) scale(1.15)"
            : "translate(-50%, -50%)",
        }}
      >
        <div className="absolute left-1/2 top-1/2 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-white" />
      </div>
    </div>
  );
}
